def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return all(isinstance(item, dict) and bool(item.get("id")) and bool(item.get("name")) for item in data) and bool(responseBody.get("requestId"))

