def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    if statusCode != 200 or responseBody.get("code") != 0 or not responseBody.get("requestId"):
        return False
    data = responseBody.get("data")
    if not isinstance(data, dict):
        return False
    for key in ("good_count", "neutral_count", "bad_count", "total_count"):
        if not isinstance(data.get(key), int):
            return False
    if data["good_count"] != 1 or data["neutral_count"] != 1 or data["bad_count"] != 1 or data["total_count"] != 3:
        return False
    good_rate = data.get("good_rate")
    bad_rate = data.get("bad_rate")
    if not isinstance(good_rate, (int, float)) or not isinstance(bad_rate, (int, float)):
        return False
    return abs(good_rate - 1.0 / 3.0) <= 0.0001 and abs(bad_rate - 1.0 / 3.0) <= 0.0001
